"""Comparador didáctico y ficha de investigación del prototipo."""

def scenario_lab():
    controls=''
    for code,name,n,p in [('a','A',10,10),('b','B',2,50)]:
        controls+=f'''<div class="scenario"><h4>Escenario {name}</h4><label for="escenario-{code}-n">Disparos de {name}: <output id="escenario-{code}-n-valor">{n}</output></label><input id="escenario-{code}-n" type="range" min="1" max="30" value="{n}"><label for="escenario-{code}-p">Probabilidad por disparo de {name}: <output id="escenario-{code}-p-valor">{p} %</output></label><input id="escenario-{code}-p" type="range" min="0" max="100" value="{p}"><dl><dt>Goles esperados</dt><dd id="escenario-{code}-xg">1</dd><dt>Probabilidad de al menos un gol</dt><dd id="escenario-{code}-gol" class="result"></dd></dl></div>'''
    return '<article class="lab-wide" aria-labelledby="titulo-escenarios"><p class="eyebrow">EXPERIMENTO 04 · COMPARA DOS ESCENARIOS</p><h3 id="titulo-escenarios">Mismo xG, distinta historia</h3><p>Diez ocasiones pequeñas o dos grandes: ¿es lo mismo sumar 1 gol esperado?</p><div class="scenario-grid">'+controls+'</div><p id="escenarios-lectura" role="status"></p><button id="escenarios-restablecer" type="button">Volver al ejemplo de 1 xG</button><details><summary>Qué estamos comparando</summary><p>Cada escenario supone remates independientes y una probabilidad constante dentro del escenario. El valor esperado es n × p; la probabilidad de marcar al menos una vez es 1 − (1 − p)ⁿ. Tener el mismo valor esperado no obliga a tener la misma distribución de goles.</p><p>No es una recomendación táctica ni un modelo de partido: no se incluyen rivales, posesiones, tiempo ni dificultad variable entre remates.</p></details><noscript><p>El ejemplo A suma 1 xG con 10 remates al 10 %; el B, con 2 al 50 %. La probabilidad de al menos un gol es aproximadamente 65,1 % en A y 75 % en B.</p></noscript></article>'

RESEARCH_FIELDS=[
 ('pregunta','Pregunta de investigación',300,'¿Qué quieres averiguar?'),
 ('hipotesis','Hipótesis inicial',500,'¿Qué esperas encontrar y qué resultado la pondría en duda?'),
 ('fuentes','Datos y fuentes',1200,'Anota procedencia, fecha de corte, cobertura y condiciones de uso.'),
 ('metodo','Método',1200,'Explica las variables, el procedimiento y una referencia con la que comparar.'),
 ('validacion','Validación',1200,'¿Cómo comprobarás el resultado con datos que no hayas usado para ajustar?'),
 ('limites','Límites del análisis',1000,'¿Qué conclusiones no permiten sacar estos datos?')
]
def research_form():
    fields=''
    for key,label,limit,hint in RESEARCH_FIELDS:
        required=' required' if key=='pregunta' else ''
        fields+=f'<div><label for="pro-{key}">{label}</label><p class="field-hint" id="pro-{key}-ayuda">{hint}</p><textarea id="pro-{key}" maxlength="{limit}" rows="3" aria-describedby="pro-{key}-ayuda"{required}></textarea></div>'
    return '<form id="pro-ficha" class="research-form"><p class="eyebrow">CUADERNO DE INVESTIGACIÓN</p><h3>Deja preparada la pregunta antes de calcular</h3><p>Completa una ficha de trabajo. Es un borrador personal, no un resultado validado. Puedes guardarlo en este navegador o descargarlo; no se envía a ningún servicio.</p><div class="research-fields">'+fields+'</div><p id="pro-estado" role="status"></p><div><button type="submit">Descargar ficha de investigación</button><button id="pro-guardar" type="button">Guardar borrador en este navegador</button><button id="pro-borrar" type="button">Borrar borrador</button></div><noscript><p>Para guardar o descargar la ficha necesitas JavaScript. Puedes copiar tus respuestas a un documento.</p></noscript></form>'


def editorial_form():
    return '''<article class="lab-wide" aria-labelledby="editorial-titulo"><p class="eyebrow">MESA DE REDACCIÓN · BORRADOR</p><h3 id="editorial-titulo">De dos jornadas a una publicación</h3><p>Prepara una ficha descriptiva con los marcadores, la cobertura y los enlaces a las fuentes. Añade tu pregunta y tu lectura antes de descargar. No se publica ni se guarda automáticamente.</p><form id="editorial-form" class="research-form"><div class="filter-grid"><div><label for="editorial-a">Primera jornada</label><select id="editorial-a" required></select></div><div><label for="editorial-b">Segunda jornada</label><select id="editorial-b" required></select></div></div><label for="editorial-pregunta">La pregunta de tu publicación</label><input id="editorial-pregunta" maxlength="240" placeholder="¿Qué quiero comparar?" required><label for="editorial-nota">Tu lectura (opcional)</label><textarea id="editorial-nota" maxlength="1500" rows="4" placeholder="Separa lo observado de tu interpretación."></textarea><button type="submit">Preparar borrador</button><p id="editorial-estado" role="status"></p><div id="editorial-salida" hidden><label for="editorial-texto">Borrador para revisar</label><textarea id="editorial-texto" rows="16" readonly></textarea><button id="editorial-descargar" type="button">Descargar borrador de publicación</button></div></form><noscript><p>Activa JavaScript para preparar la ficha. Los talleres de comparación y mapas siguen disponibles arriba.</p></noscript></article>'''


def museum_notebook():
    return '''<article class="lab-wide" aria-labelledby="museo-cuaderno-titulo"><p class="eyebrow">CUADERNO DE VISITA · MIRAR ANTES DE CONCLUIR</p><h3 id="museo-cuaderno-titulo">Tu lectura también forma parte de la visita</h3><div class="grid"><details><summary>Pista para la sala de conexiones</summary><p>Compara el tamaño de los círculos con el color destacado. ¿Representan la misma propiedad?</p><details><summary>Contrastar mi interpretación</summary><p>No: volumen de pases e intermediación describen propiedades distintas. Una jugadora puede conectar caminos entre compañeras sin ser quien acumula más pases. Comprueba también el periodo y el umbral de pases incluidos en la red.</p></details></details><details><summary>Pista para la sala de territorio</summary><p>Busca la dirección de ataque y compara el valor del origen con el del destino de un pase.</p><details><summary>Contrastar mi interpretación</summary><p>En este modelo el cambio de amenaza de una acción completada es valor del destino menos valor del origen. Un cambio positivo no demuestra que fuera la mejor decisión: el mapa no incorpora todas las alternativas ni los movimientos sin balón.</p></details></details></div><form id="museo-cuaderno" class="research-form"><label for="museo-obra">Obra que estoy observando</label><select id="museo-obra"><option value="red">Sala 01 · Red de pases</option><option value="territorio">Sala 02 · Superficie de amenaza</option></select><label for="museo-observo">Lo que observo en el gráfico</label><textarea id="museo-observo" maxlength="1200" rows="3" required placeholder="Describe un elemento visible: tamaño, color, posición o diferencia."></textarea><label for="museo-interpreto">Mi interpretación (opcional)</label><textarea id="museo-interpreto" maxlength="1200" rows="3" placeholder="¿Qué podría significar? Separa la hipótesis de lo observado."></textarea><label for="museo-falta">Lo que necesitaría comprobar (opcional)</label><textarea id="museo-falta" maxlength="1200" rows="3" placeholder="Periodo, cobertura, definiciones, contexto o alternativas."></textarea><p>No se guarda automáticamente. Descarga tu lectura para conservarla; incluye el enlace a la obra y su metodología.</p><button type="submit">Descargar mi cuaderno de visita</button><p id="museo-cuaderno-estado" role="status"></p><noscript><p>Las pistas y explicaciones funcionan sin JavaScript. Para descargar el cuaderno necesitas activarlo, o puedes copiar tus notas.</p></noscript></form></article>'''
